d=$(mktemp -d); B=$d/.jidoka/board; mkdir -p $B/_mail; now=$(date +%s)000; for p in 'sess-a app/inbox/**' 'sess-b app/inbox/Thread.tsx' 'sess-c lib/billing/**' 'sess-d lib/billing/**'; do s=${p%% *}; c=${p#* }; printf '{"session":"%s","pid":null,"worktree":"%s/no-wt-%s","repo":"r-%s","branch":"b-%s","claims":["%s"],"startedAt":%s,"updatedAt":%s,"status":"working"}
