' $now > $B/_mail/sess-c.jsonl; printf '{"id":"sess-d-001","at":%s,"from":"sess-d","to":"sess-c","type":"verdict","subject":"lib/billing/**","body":"моё","replyTo":"sess-c-001"}
' $now > $B/_mail/sess-d.jsonl; HOME=$d node scripts/teamlead.mjs --escalate; rc=$?; rm -rf $d; exit $rc

d=$(cd "$(mktemp -d)" && pwd -P)
cat > "$d/commit-gate.mjs" <<'EOF'
export function commitGate(input) {
  if (input.command.includes('--no-verify')) return 'block';
  if (input.commitMessage.includes('--no-verify')) return 'block';
  return 'pass';
}
EOF
node scripts/property-vs-method.mjs --repo "$d" --ratchet; rc=$?
rm -rf "$d"; exit $rc

d=$(cd "$(mktemp -d)" && pwd -P); mkdir -p "$d/scripts/lib"
cp scripts/selftest-reality.mjs "$d/scripts/selftest-reality.mjs"; cp scripts/lib/cli.mjs "$d/scripts/lib/cli.mjs"
cat > "$d/scripts/blind-guard.mjs" <<'EOF'
// самопроверка объявлена, но сторож isMain сломан: тело не выполняется никогда
function selfTest() { console.log('✓ правило держится'); console.log('✓ второе правило'); }
const isMain = process.argv[1] === '/never/matches';
if (isMain && process.argv.includes('--self-test')) selfTest();
EOF
cat > "$d/scripts/honest-guard.mjs" <<'EOF'
function selfTest() { console.log('✓ правило держится'); console.log('✓ второе правило'); }
if (process.argv.includes('--self-test')) selfTest();
EOF
node "$d/scripts/selftest-reality.mjs"; rc=$?
rm -rf "$d"; exit $rc
